quickStart.snippet:
# نصب پایه + یک کامپوننت
pnpm add @virtari-packages/core @virtari-packages/tokens @virtari-packages/react-button

# یک‌بار CSS را در ریشهٔ اپ ایمپورت کنید
@import "@virtari-packages/core";
@import "@virtari-packages/tokens";
@import "@virtari-packages/react-button/styles";

# استفاده
import { Button } from "@virtari-packages/react-button";
<Button variant="outline">کلیک کن</Button>

architecture.snippet:
@virtari-packages/tokens       → توکن‌های دیزاین (ویژگی‌های سفارشی CSS)
@virtari-packages/core         → ترتیب @layer، ریست، استایل‌های پایه
@virtari-packages/react-*      → یک پکیج به ازای هر کامپوننت
